<template><ContentWrap><el-form inline @submit.prevent><el-form-item label="学员姓名"><el-input v-model="query.studentName" clearable/></el-form-item><el-form-item label="订单号"><el-input v-model="query.orderNo" clearable/></el-form-item><el-form-item label="礼品"><el-input v-model="query.giftKeyword" clearable/></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form><el-table v-loading="loading" :data="rows" border><el-table-column v-for="c in visibleColumns" :key="c.key" :prop="c.key" :label="c.label" :min-width="c.width"><template #default="{ row }"><span v-if="c.key==='giftItemsJson'">{{ formatGift(row.giftItemsJson) }}</span><span v-else>{{ row[c.key] || '-' }}</span></template></el-table-column></el-table><el-pagination class="mt-16px" background layout="total, sizes, prev, pager, next" :total="total" v-model:current-page="query.pageNo" v-model:page-size="query.pageSize" @change="load"/></ContentWrap></template>
<script setup lang="ts">import { ref, computed, onMounted } from 'vue'; import { getGiftPurchasePage, type GiftPurchaseVO } from '@/api/zsjos/gift'; const loading=ref(false), rows=ref<GiftPurchaseVO[]>([]), total=ref(0); const query:any=ref({pageNo:1,pageSize:20}); const columns=[{key:'studentName',label:'学员姓名',width:120},{key:'studentMobile',label:'手机号',width:130},{key:'studentWechatId',label:'微信号',width:130},{key:'giftItemsJson',label:'礼品',width:240},{key:'shippingAddress',label:'邮寄地址',width:260},{key:'orderNo',label:'订单号',width:160},{key:'generatedAt',label:'生成时间',width:180}]; const visibleColumns=computed(()=>columns); const formatGift=(v?:string)=>{if(!v)return '-';try{const a=JSON.parse(v);return Array.isArray(a)?a.map((x:any)=>x.name||x.label||x.code||x).join('、'):v}catch{return v}}; const load=async()=>{loading.value=true;try{const r:any=await getGiftPurchasePage(query.value);const d=r.data||r;rows.value=d.list||d.records||[];total.value=d.total||0}finally{loading.value=false}};onMounted(load)</script>
